-- Venue Live Guest "Wedding Mediterania". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara mediterania), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'mediterania', 'Wedding Mediterania', 'mediterania', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 147, 'center 38%',
  $t${"name":"Mediterania","orn":"diamond","ui":{"ivory":"#F6F4EE","white":"#FFFFFF","soft":"#DDE3EE","soft2":"#C9A24A","accent":"#2F5AA8","deep":"#1E2F5A","ink":"#1E2F5A","mute":"#6F7C99","line":"#D3DAE8","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#F3EFE4","ink":"#1E2F5A","accent":"#2F5AA8","gold":"#C9A24A","leaf":"#DDE3EE","hbg":"rgba(246,244,238,.94)","hline":"#C9A24A","motif":"diamond"},"hud":{"bg":"rgba(30,47,90,.9)","acc":"#F2C94C","on":"#1E2F5A"},"scr":{"wine":"#1E2F5A","veil":"246,244,238"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'mediterania');
update public.live_venues set decor = $d${"speakers":{"url":"/assets/live-decor/mediterania/speakers.webp","w":2.2},"balloons":{"url":"/assets/live-decor/mediterania/balloons.webp","w":1.3,"x":3.3,"z":-18,"mirror":true},"stall_snacks":{"url":"/assets/live-decor/mediterania/stall_snacks.webp","w":2.8},"stall_candy":{"url":"/assets/live-decor/mediterania/stall_candy.webp","w":8.6,"x":-14.5,"z":4.5},"stall_drinks":{"url":"/assets/live-decor/mediterania/stall_drinks.webp","w":10.2,"x":-9.4,"z":-11.5},"photobooth":{"url":"/assets/live-decor/mediterania/photobooth.webp","w":6.4},"claw":{"url":"/assets/live-decor/mediterania/claw.webp","w":9.0},"arch":{"url":"/assets/live-decor/mediterania/arch.webp"},"fountain":{"url":"/assets/live-decor/mediterania/fountain.webp","w":7.6,"x":9.3,"z":-15.5},"sign":{"url":"/assets/live-decor/mediterania/sign.webp","w":1.7,"x":-5.6,"z":9},"easel":{"url":"/assets/live-decor/mediterania/easel.webp","w":4.4,"x":5.2,"z":10.0},"table":{"url":"/assets/live-decor/mediterania/table.webp","w":3.6,"x":-8.8,"z":3.6},"banner":{"url":"/assets/live-decor/mediterania/banner.webp","w":1.5,"x":9.6,"z":8.8},"gifts":{"url":"/assets/live-decor/mediterania/gifts.webp","w":2.0},"lamp":{"url":"/assets/live-decor/mediterania/lamp.webp","w":1.4,"x":3.3,"z":-12,"mirror":true},"rope":{"url":"/assets/live-decor/mediterania/rope.webp","w":2.2,"x":3.3,"z":-6,"mirror":true},"planter":{"url":"/assets/live-decor/mediterania/planter.webp","w":1.4,"x":3.3,"z":0,"mirror":true},"bush":{"url":"/assets/live-decor/mediterania/bush.webp","w":1.3,"x":3.3,"z":6,"mirror":true},"av_host":{"url":"/assets/live-decor/mediterania/av_host.webp","name":"Pengantin"},"av_l1":{"url":"/assets/live-decor/mediterania/av_l1.webp","name":"Kak Blazer Krem"},"av_l2":{"url":"/assets/live-decor/mediterania/av_l2.webp","name":"Kak Rompi Biru"},"av_l3":{"url":"/assets/live-decor/mediterania/av_l3.webp","name":"Kak Topi Jerami"},"av_p1":{"url":"/assets/live-decor/mediterania/av_p1.webp","name":"Kak Gaun Bunga Biru"},"av_p2":{"url":"/assets/live-decor/mediterania/av_p2.webp","name":"Kak Hijab Krem"},"av_p3":{"url":"/assets/live-decor/mediterania/av_p3.webp","name":"Kak Topi Rok Biru"}}$d$::jsonb, background_url = '/assets/live-decor/mediterania/painting.webp', active = true, updated_at = now() where key = 'mediterania';
